#!/usr/bin/env bash
# Waypoint setup: walks you through Firebase, Google sign-in, Anthropic and
# Tailscale, and writes .env (server) and app/.env (phone app). Re-run any time:
# it keeps values already saved. Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


SERVER_ENV=".env"
APP_ENV="app/.env"
PACKAGE="app.waypoint"
KEYSTORE="app/android/app/debug.keystore"
SA_FILE="secrets/firebase-service-account.json"

# use_env FILE points ask/write_env at the server's or the app's .env.
use_env() { ENV_FILE="$1"; }

# newest_download GLOB prints the most recent file in ~/Downloads matching GLOB.
newest_download() {
  local f
  f=$(ls -t "$HOME"/Downloads/$1 2>/dev/null | head -n1 || true)
  printf '%s' "$f"
}

# take_download GLOB DEST "what" moves the newest matching download to DEST.
take_download() {
  local glob="$1" dest="$2" what="$3" found
  if [[ -f "$dest" ]] && confirm "$dest is already there. Keep it?"; then return 0; fi
  while :; do
    found=$(newest_download "$glob")
    if [[ -n "$found" ]] && confirm "Use $found as $what?"; then break; fi
    say "I couldn't find it in ~/Downloads, or you said no."
    ask DOWNLOAD_PATH "Path to $what (drag the file here):"
    found="${DOWNLOAD_PATH//\\ / }"; found="${found%\'}"; found="${found#\'}"
    [[ -f "$found" ]] && break
    warn "No file at $found."
  done
  mkdir -p "$(dirname "$dest")"
  mv "$found" "$dest"
  chmod 600 "$dest"
  printf '  %s✓ moved%s %s → %s\n' "$GREEN" "$RESET" "$(basename "$found")" "$dest"
}

run_wizard() {

cd "$(dirname "$0")/.."
# Ignore same-named variables from your shell (an exported ANTHROPIC_API_KEY,
# say): every value comes from this run or from the .env files.
unset FIREBASE_PROJECT_ID GOOGLE_WEB_CLIENT_ID ANTHROPIC_API_KEY EXPO_PUBLIC_API_URL

TOTAL_STAGES=9

banner "Waypoint setup: Firebase, Google sign-in, Anthropic, Tailscale"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Local secrets for MySQL and access tokens"
say "These never leave your machine. Existing values are kept: changing the"
say "MySQL passwords after the database was created would lock the API out."
use_env "$SERVER_ENV"
v=$(_existing MYSQL_PASSWORD || true);      [[ -n "$v" ]] || v=$(openssl rand -hex 24)
write_env MYSQL_PASSWORD "$v"
v=$(_existing MYSQL_ROOT_PASSWORD || true); [[ -n "$v" ]] || v=$(openssl rand -hex 24)
write_env MYSQL_ROOT_PASSWORD "$v"
v=$(_existing JWT_KEY || true);             [[ -n "$v" ]] || v=$(openssl rand -base64 48 | tr -d '\n')
write_env JWT_KEY "$v"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Firebase: create the project"
say "One Firebase project holds push (FCM) and is also the Google Cloud"
say "project for Google sign-in. Already made one? Just copy its ID."
open_url "https://console.firebase.google.com/"
step "Create a new project (or Add project). Name it Waypoint."
step "Turn Google Analytics off; it isn't used. Click Create project."
step "Open the gear → Project settings → General and copy the Project ID."
until [[ "${FIREBASE_PROJECT_ID:-}" =~ ^[a-z0-9-]{6,30}$ ]]; do
  ask FIREBASE_PROJECT_ID "Project ID (e.g. waypoint-1a2b3):"
done
PID="$FIREBASE_PROJECT_ID"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Android signing key fingerprint (SHA-1)"
say "Google sign-in only answers an app whose package and signing key it knows."
say "Expo signs debug and the README's release APK with app/android's debug key."
if [[ ! -f "$KEYSTORE" ]]; then
  warn "$KEYSTORE doesn't exist yet: android/ is generated by expo prebuild."
  if confirm "Run 'npx expo prebuild --platform android' in app/ now?"; then
    [[ -d app/node_modules ]] || npm ci --prefix app
    (cd app && npx expo prebuild --platform android)
  fi
fi
SHA1=""
if [[ -f "$KEYSTORE" ]] && command -v keytool >/dev/null 2>&1; then
  SHA1=$(keytool -list -v -keystore "$KEYSTORE" -alias androiddebugkey \
           -storepass android -keypass android 2>/dev/null \
         | awk '/SHA1:/ {print $2; exit}' || true)
fi
if [[ -n "$SHA1" ]]; then
  say "SHA-1 of $KEYSTORE:"
  printf '\n    %s%s%s\n\n' "$BOLD" "$SHA1" "$RESET"
else
  warn "Couldn't read the keystore. Get the SHA-1 with './gradlew signingReport' in app/android."
  ask SHA1 "Paste the SHA-1:"
fi
note "Copy it now: the next two stages ask for it. If you ever sign with your own"
note "release keystore, add that key's SHA-1 in the same places."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Firebase: register the Android app"
open_url "https://console.firebase.google.com/project/$PID/settings/general"
step "Under Your apps, click Add app → the Android icon."
step "Package name: $PACKAGE   App nickname: Waypoint"
step "Debug signing certificate SHA-1: $SHA1"
step "Register app → Download google-services.json → skip the remaining steps."
note "Already registered? Open the app's card and download google-services.json there,"
note "and check the SHA-1 is listed under SHA certificate fingerprints."
pause "Press Enter once google-services.json has downloaded"
take_download "google-services*.json" "app/google-services.json" "google-services.json"
grep -q "\"$PACKAGE\"" app/google-services.json \
  || warn "That file doesn't mention $PACKAGE. Re-download it from the right app."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Google sign-in: consent screen and test user"
open_url "https://console.cloud.google.com/auth/overview?project=$PID"
step "If it says Google Auth Platform not configured yet, click Get started."
step "App name: Waypoint. Support email: yours. Audience: External."
step "Contact email: yours. Agree to the policy → Create."
step "Then Audience → Test users → Add users → the Google account on your phone."
note "Leave the app in Testing: only test users can sign in, which is what you want."
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Google sign-in: Web and Android clients"
open_url "https://console.cloud.google.com/auth/clients?project=$PID"
say "The phone asks Google for an ID token issued to the Web client; the server"
say "checks tokens against that same ID. The Android client just has to exist."
step "Web: if 'Web client (auto created by Google Service)' is listed, use it."
step "     Otherwise Create client → Web application → name 'Waypoint server' → Create."
step "Android: if no Android client lists $PACKAGE, Create client → Android,"
step "     package $PACKAGE, SHA-1 $SHA1 → Create."
note "'Already in use' on the Android client means another Google Cloud project"
note "already has this package + SHA-1; delete it there first."
step "Copy the Web client's Client ID."
use_env "$SERVER_ENV"
until [[ "${GOOGLE_WEB_CLIENT_ID:-}" == *.apps.googleusercontent.com ]]; do
  ask GOOGLE_WEB_CLIENT_ID "Web client ID (ends .apps.googleusercontent.com):"
done
write_env GOOGLE_WEB_CLIENT_ID "$GOOGLE_WEB_CLIENT_ID"
use_env "$APP_ENV"
write_env EXPO_PUBLIC_GOOGLE_WEB_CLIENT_ID "$GOOGLE_WEB_CLIENT_ID"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Firebase: server credentials for push"
open_url "https://console.firebase.google.com/project/$PID/settings/serviceaccounts/adminsdk"
step "Click Generate new private key → Generate key. A JSON file downloads."
note "It's a password for your project: it goes to $SA_FILE, which git ignores."
pause "Press Enter once the key has downloaded"
take_download "*firebase-adminsdk*.json" "$SA_FILE" "the service-account key"
chmod 700 secrets
grep -q "\"project_id\": \"$PID\"" "$SA_FILE" \
  || warn "That key isn't for project $PID. Check you downloaded it from the right project."
open_url "https://console.firebase.google.com/project/$PID/settings/cloudmessaging"
step "Check 'Firebase Cloud Messaging API (V1)' says Enabled. If not, enable it."
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Anthropic: API key and spend guard"
open_url "https://console.anthropic.com/settings/keys"
step "Create Key → name it waypoint-server → copy it (it's shown once)."
use_env "$SERVER_ENV"
until [[ "${ANTHROPIC_API_KEY:-}" == sk-ant-* ]]; do
  ask_secret ANTHROPIC_API_KEY "Paste the key (starts sk-ant-):"
done
write_env ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"
open_url "https://console.anthropic.com/settings/limits"
step "Set the monthly spend limit to \$10."
step "Add an email notification at \$8."
note "That's the spec's spend guard: a bug can't run up a bill."
pause "Press Enter once the limit and the alert are saved"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Tailscale: how the phone reaches the API"
say "The API runs on this machine at port 8080, reached over your tailnet only."
use_env "$APP_ENV"
TS_NAME=""
if command -v tailscale >/dev/null 2>&1; then
  TS_NAME=$(tailscale status --json 2>/dev/null \
    | python3 -c 'import json,sys; print(json.load(sys.stdin)["Self"]["DNSName"].rstrip("."))' 2>/dev/null || true)
fi
if [[ -n "$TS_NAME" ]] && confirm "Use http://$TS_NAME:8080 as the API address?"; then
  EXPO_PUBLIC_API_URL="http://$TS_NAME:8080"
else
  until [[ "${EXPO_PUBLIC_API_URL:-}" == http*://* ]]; do
    ask EXPO_PUBLIC_API_URL "API address (e.g. http://my-pc.tailnet.ts.net:8080):"
  done
fi
write_env EXPO_PUBLIC_API_URL "$EXPO_PUBLIC_API_URL"
step "Install Tailscale on the phone and sign in to the same tailnet."
pause

finish
say "Next:"
step "Server: docker compose up --build"
step "App:    cd app && npx expo prebuild --platform android --clean && npx expo run:android"
note "Prebuild again whenever app/.env or app/google-services.json changes."
printf '\n'
}

run_wizard "$@"; exit
